package com.rohit.inventory.repository;
import com.rohit.inventory.entity.*; import java.util.Optional; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface ProductRepository extends JpaRepository<Product, UUID> { Optional<Product> findBySku(String sku); Optional<Product> findByBarcode(String barcode); @Query("select distinct p from Product p left join p.suppliers s where (:search is null or lower(p.sku) like lower(concat('%',:search,'%')) or lower(p.name) like lower(concat('%',:search,'%')) or lower(coalesce(p.barcode,'')) like lower(concat('%',:search,'%'))) and (:status is null or p.status=:status) and (:categoryId is null or p.category.id=:categoryId) and (:supplierId is null or s.id=:supplierId)") Page<Product> search(@Param("search") String search,@Param("status") ProductStatus status,@Param("categoryId") UUID categoryId,@Param("supplierId") UUID supplierId,Pageable pageable); }
